{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"rent_increase_limits","lifecycle":"enacted","title":"Berkeley Rent Stabilization Ordinance — rent control coverage","requirement":"Rent control applies to most multifamily units built before 1980, single-family homes with tenancies beginning before 1996, and certain rooming houses; post-June-1980 construction, condominiums and certain subsidized units are registered but not rent-controlled.","key_value":null,"coverage_conditions":"Fully covered for rent control: most multifamily units built before 1980, single-family homes with tenancies that began before 1996, and single-family rooming houses with five or more rooms rented individually.","applicability":{"conditions":[{"type":"built","role":"exempt","op":"after","date":"1980-06","basis":"certificate_of_occupancy"},{"type":"owner","role":"exempt","who":"owner-occupied duplex (Golden Duplex)","unit_limit":2},{"type":"other","role":"exempt","text":"most condominiums"},{"type":"other","role":"exempt","text":"units with listed government subsidies such as Section 202, Section 811, or project-based Section 8 with a HUD-insured mortgage"}],"per_tenancy":"Single-family homes whose tenancy began on or after January 1, 1996; units where the owner shares a kitchen or bath with the tenant; tenancies started after Nov 7, 2018, where one unit is an ADU and either is owner-occupied.","coverage_quotes":["Most units in multifamily properties built before 1980**","New construction: units that were built and received a Certificate of Occupancy after June 1980**","“Golden Duplex”: duplex that was owner-occupied on December 31, 1979, and currently has an owner living in one of the units"]},"exemptions":"Golden Duplex (owner-occupied since Dec 31, 1979); unit where the owner shares a kitchen or bath with the tenant; tenancies after Nov 7, 2018 in owner-occupied ADU properties; university rental units such as dormitories; nonprofit cooperative.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Berkeley Eviction for Just Cause Ordinance coverage","requirement":"A landlord may evict only for just cause from covered units, including partially covered units such as post-June-1980 construction, condominiums and certain subsidized units.","key_value":null,"coverage_conditions":"Just cause applies to fully covered units (most multifamily buildings built before 1980, pre-1996 single-family tenancies, rooming houses) and to partially covered units (post-June-1980 construction, condominiums, certain subsidized units).","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied duplex (Golden Duplex)","unit_limit":2}],"per_tenancy":"Unit where the owner shares a kitchen or bath with the tenant and lived on the property when the tenancy started; tenancies started after Nov 7, 2018, where one unit is an ADU and either is owner-occupied.","coverage_quotes":["New construction: units that were built and received a Certificate of Occupancy after June 1980**","Most condominiums** Partially Covered Yes No Yes Yes"]},"exemptions":"Golden Duplex (owner-occupied since Dec 31, 1979); unit where the owner shares a kitchen or bath with the tenant; tenancies after Nov 7, 2018 in owner-occupied ADU properties; university rental units such as dormitories; nonprofit cooperative.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"New construction: units that were built and received a Certificate of Occupancy after June 1980** Partially Covered Yes No Yes Yes","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D009-01","doc_id":"D009","jurisdiction":"Berkeley, CA","category":"security_deposits","lifecycle":"enacted","title":"Berkeley Rent Ordinance security deposit interest coverage","requirement":"Landlords must pay interest on security deposits held for units covered by the ordinance, including partially covered units such as post-June-1980 construction and condominiums.","key_value":null,"coverage_conditions":"Security deposit interest applies to fully covered units (most multifamily buildings built before 1980, pre-1996 single-family tenancies, rooming houses) and to partially covered units.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied duplex (Golden Duplex)","unit_limit":2}],"per_tenancy":"Unit where the owner shares a kitchen or bath with the tenant and lived on the property when the tenancy started; tenancies started after Nov 7, 2018, where one unit is an ADU and either is owner-occupied.","coverage_quotes":["Security Deposit\nInterest","Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes"]},"exemptions":"Golden Duplex; unit where the owner shares a kitchen or bath with the tenant; tenancies after Nov 7, 2018 in owner-occupied ADU properties; university rental units such as dormitories; nonprofit cooperative.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.76","quoted_span":"Security Deposit Interest Most units in multifamily properties built before 1980** Fully Covered Yes Yes Yes Yes","interaction":null,"relations":[],"confidence":0.7,"conflict_flag":false,"conflict_note":null}
